function hat(t, gainVal = .035) {
	const c = audio();
	const src = c.createBufferSource();
	src.buffer = noiseBuffer(.4, "white");
	const f = c.createBiquadFilter();
	f.type = "highpass";
	f.frequency.value = 8e3;
	const g = c.createGain();
	g.gain.setValueAtTime(gainVal, t);
	g.gain.exponentialRampToValueAtTime(1e-4, t + .05);
	src.connect(f).connect(g).connect(master);
	src.start(t);
	src.stop(t + .06);
}
function chord(t, freqs, dur = 2.4, gainVal = .05, type = "sawtooth") {
	const c = audio();
	const g = c.createGain();
	const f = c.createBiquadFilter();
	f.type = "lowpass";
	f.frequency.setValueAtTime(700, t);
	f.frequency.linearRampToValueAtTime(1600, t + dur * .4);
	g.gain.setValueAtTime(0, t);
	g.gain.linearRampToValueAtTime(gainVal, t + .25);
	g.gain.exponentialRampToValueAtTime(1e-4, t + dur);
	for (const fr of freqs) {
		const o = c.createOscillator();
		o.type = type;
		o.frequency.value = fr;
		o.connect(f);
		o.start(t);
		o.stop(t + dur);
		nodes.push(o);
	}
	f.connect(g).connect(master);
	nodes.push(f, g);
}
/** Bucle rítmico genérico con tempo dado. */
function groove(bpm, pattern) {
	const c = audio();
	const step = 60 / bpm / 2;
	let i = 0;
	const tick = () => {
		const t = c.currentTime + .05;
		pattern(i, t);
		i++;
		timers.push(setTimeout(tick, step * 1e3));
	};
	tick();
}
